using Dip.Application.Abstractions.Persistence;using Dip.Domain.Enums;
namespace Dip.Application.Features.Intelligence;
public sealed class AdaptiveQaPlanner
{
    readonly IEvidenceRepository _evidence;public AdaptiveQaPlanner(IEvidenceRepository evidence){_evidence=evidence;}
    public async Task<AdaptiveQaPlan> PlanAsync(AdaptiveQaRequest r,CancellationToken ct){var ev=await _evidence.ListForProjectAsync(r.ProjectId,DateTimeOffset.UtcNow.AddDays(-90),ct);var fail=ev.Count(x=>x.Outcome==EvidenceOutcome.Failed);var total=Math.Max(1,ev.Count);var hist=Math.Min(100m,decimal.Round(100m*fail/total,2));var p=string.Join('|',r.ChangedPaths).ToLowerInvariant();var items=new List<QaPlanItem>();void A(string k,string reason,int min,decimal risk,bool req=false)=>items.Add(new(k,reason,min,risk,req));if(r.ChangedPaths.Count==0||p.Contains("readme")&&r.ChangedPaths.All(x=>x.Contains("readme",StringComparison.OrdinalIgnoreCase)))A("fast-sanity","Documentation-only change; full QA is not justified.",1,5,true);else{A("language-build-test","Source changed; compile and focused tests are baseline evidence.",4,55,true);if(p.Contains("render")||p.Contains("shader")||p.Contains("material")||p.Contains("ui")){A("visual-regression","Rendering/UI paths changed.",5,80,true);A("gpu-performance","Rendering change can affect frame time.",8,75);}if(p.Contains("android")||p.Contains("mobile")||p.Contains("ios")){A("mobile-envelope","Mobile-targeted files changed.",12,90,true);A("thermal-soak","Mobile changes carry thermal risk.",30,75);}if(p.Contains("memory")||p.Contains("alloc")||p.Contains("stream"))A("memory-soak","Memory-sensitive path changed.",20,85,true);if(hist>20)A("historical-risk-repeat","Recent project evidence has elevated failure history.",10,Math.Min(100,hist+30),true);}var selected=items.Where(x=>x.Required).ToList();foreach(var x in items.Where(x=>!x.Required).OrderByDescending(x=>x.RiskWeight)){if(selected.Sum(y=>y.EstimatedMinutes)+x.EstimatedMinutes<=Math.Max(1,r.BudgetMinutes))selected.Add(x);}return new(selected,selected.Sum(x=>x.EstimatedMinutes),hist,$"Planned from {r.ChangedPaths.Count} changed path(s), {ev.Count} recent evidence item(s), and a {hist:0.##}% historical failure ratio.");}
}
